#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-10

# strict-mode: opt-out this harness counts failures and prints a summary, so
# `-e` would abort on the first failing assertion and hide the rest.
# `set -uo pipefail` is set below.
#
# =============================================================================
# Running a test must not modify tracked files (#4025)
# =============================================================================
# Two tests rewrote the working tree and never put it back:
#
#   tests/unit/test-mdx-compile.sh               docs/site/package.json + lock
#   tests/skills/structure/test-skill-tokens.sh  a tracked baseline, every run
#
# The mdx one is the dangerous half. On any machine without NPM_TOKEN its
# install hits a 401 and it swaps the real manifest to
# `"@yonatan-hq/analytics": "file:../stubs/analytics-stub"`. A developer who ran
# the suite before committing would stage that without noticing, shipping a
# no-op analytics to a live site. The test passes either way and says nothing
# about the tree, so `git status` is the only witness, and this defect is
# precisely what makes `git status` untrustworthy.
#
# WHAT THIS ASSERTS, AND WHAT IT DOES NOT
#
#   A. BEHAVIOURAL, for the cheap test: run test-skill-tokens.sh and require the
#      tracked-file set to be byte-identical afterwards.
#   B. STRUCTURAL, for the expensive one: test-mdx-compile.sh runs `npm ci`
#      against docs/site and takes minutes, so running it here would make this
#      guard too slow to keep. Instead assert it backs up and restores under a
#      trap.
#
# B is weaker and it is labelled as such rather than dressed up. It catches the
# regression that matters (someone deletes the restore) without turning a fast
# unit test into a multi-minute one.
# =============================================================================

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'; NC=$'\033[0m'
PASS=0; FAIL=0
pass() { echo "  ${GREEN}PASS${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo "  ${RED}FAIL${NC} $1"; FAIL=$((FAIL + 1)); }
skip() { echo "  ${YELLOW}SKIP${NC} $1"; }

echo "=========================================="
echo "  tests leave the tree clean (#4025)"
echo "=========================================="

# Hash the SPECIFIC files at risk, rather than diffing `git status`.
#
# The first version of this compared whole-tree `git status` before and after,
# and skipped when the tree was already dirty. That made it VACUOUS in exactly
# the situation it is needed: mid-change, with other edits in flight. Measured
# during development, reverting the skill-tokens gate left this guard GREEN
# because the revert itself dirtied the tree and tripped the skip.
#
# Hashing named files works on a dirty tree, needs no skip path, and cannot
# fail open. Unrelated edits are invisible to it by construction.
AT_RISK=(
  "tests/skills/structure/.skill-tokens-baseline.json"
  "docs/site/package.json"
  "docs/site/package-lock.json"
)

hash_at_risk() {
  local f
  for f in "${AT_RISK[@]}"; do
    if [[ -f "$REPO_ROOT/$f" ]]; then
      printf '%s  %s\n' "$(shasum -a 256 "$REPO_ROOT/$f" | cut -d' ' -f1)" "$f"
    else
      printf 'ABSENT  %s\n' "$f"
    fi
  done
}

BEFORE="$(hash_at_risk)"

# silent: known-noise the subject's own output is not the assertion; its exit
# status is deliberately ignored, because a FAILING test must still leave the
# tree as it found it.
bash tests/skills/structure/test-skill-tokens.sh >/dev/null 2>&1
AFTER="$(hash_at_risk)"

if [[ "$BEFORE" == "$AFTER" ]]; then
  pass "test-skill-tokens.sh leaves the at-risk files untouched"
else
  fail "test-skill-tokens.sh modified a tracked file:"
  diff <(printf '%s\n' "$BEFORE") <(printf '%s\n' "$AFTER") | sed 's/^/         /'
fi

# Positive control: the opt-in path must still work, or the fix has deleted a
# feature rather than gating it.
# silent: known-noise same reason as above
SKILL_TOKENS_WRITE_BASELINE=1 bash tests/skills/structure/test-skill-tokens.sh >/dev/null 2>&1
if [[ "$(hash_at_risk)" != "$BEFORE" ]]; then
  pass "the opt-in flag still writes the baseline"
  # silent: post-cleanup putting back what this test deliberately dirtied
  git -C "$REPO_ROOT" checkout -- tests/skills/structure/.skill-tokens-baseline.json 2>/dev/null
else
  fail "SKILL_TOKENS_WRITE_BASELINE=1 wrote nothing; the feature is gone, not gated"
fi

MDX="tests/unit/test-mdx-compile.sh"
if [[ ! -f "$MDX" ]]; then
  fail "$MDX not found"
else
  if grep -q 'restore_docs_site_manifests' "$MDX"; then
    pass "$MDX defines a restore for the manifests it swaps"
  else
    fail "$MDX has no restore; its stub swap would leak into the working tree"
  fi
  # Defining it is not enough. It has to be wired to EXIT, or it never runs on
  # the failure paths, which are exactly the paths that leave the swap behind.
  if grep -qE "trap '.*restore_docs_site_manifests.*' EXIT" "$MDX"; then
    pass "$MDX wires the restore to an EXIT trap"
  else
    fail "$MDX defines a restore but never traps it; failure paths would leak the swap"
  fi
fi

echo "=========================================="
echo "  Passed: $PASS  Failed: $FAIL"
echo "=========================================="
[[ $FAIL -eq 0 ]]
